const inputGroupAddonVariants = cva(
  "text-(--color-ink-muted) h-auto gap-(--spacing-sm) py-(--spacing-sm) text-(length:--text-body) font-(weight:--font-weight-medium) group-data-[disabled=true]/input-group:opacity-(--ui-alpha-disabled) [&>kbd]:rounded-(--radius-subtle) [&>svg:not([class*='size-'])]:size-(--spacing-lg) flex cursor-text items-center justify-center select-none",
  {
    variants: {
      align: {
        "inline-start": "pl-(--spacing-sm) has-[>button]:ml-[calc(var(--spacing-xs)*-1)] has-[>kbd]:ml-[calc(var(--spacing-xs)*-1)] order-first",
        "inline-end": "pr-(--spacing-sm) has-[>button]:mr-[calc(var(--spacing-xs)*-1)] has-[>kbd]:mr-[calc(var(--spacing-xs)*-1)] order-last",
        "block-start":
          "px-(--spacing-md) pt-(--spacing-sm) group-has-[>input]/input-group:pt-(--spacing-sm) [.border-b]:pb-(--spacing-sm) order-first w-full justify-start",
        "block-end":
          "px-(--spacing-md) pb-(--spacing-sm) group-has-[>input]/input-group:pb-(--spacing-sm) [.border-t]:pt-(--spacing-sm) order-last w-full justify-start",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  }
)

function InputGroupAddon({
  className,
  align = "inline-start",
  ...props
}: ReactComponentProps<"div"> & VariantProps<typeof inputGroupAddonVariants>) {
  return (
    <div
      role="group"
      data-slot="input-group-addon"
      data-align={align}
      className={cn(inputGroupAddonVariants({ align }), className)}
      onClick={(e) => {
        if ((e.target as HTMLElement).closest("button")) {
          return
        }
        e.currentTarget.parentElement?.querySelector("input")?.focus()
      }}
      {...props}
    />
  )
}

const inputGroupButtonVariants = cva(
  "gap-(--spacing-sm) text-(length:--text-body) flex items-center shadow-(--ui-elevation-none)",
  {
    variants: {
      size: {
        xs: "h-(--spacing-xl) gap-(--spacing-xs) rounded-(--radius-default) px-(--spacing-sm) [&>svg:not([class*='size-'])]:size-(--ui-control-switch-thumb)",
        sm: "",
        "icon-xs": "size-(--spacing-xl) rounded-(--radius-default) p-0 has-[>svg]:p-0",
        "icon-sm": "size-(--spacing-2xl) p-0 has-[>svg]:p-0",
      },
    },
    defaultVariants: {
      size: "xs",
    },
  }
)

function InputGroupButton({
  className,
  type = "button",
  variant = "ghost",
  size = "xs",
  ...props
}: Omit<ReactComponentProps<typeof Button>, "size" | "type"> &
  VariantProps<typeof inputGroupButtonVariants> & {
    type?: "button" | "submit" | "reset"
  }) {
  return (
    <Button
      type={type}
      data-size={size}
      variant={variant}
      className={cn(inputGroupButtonVariants({ size }), className)}
      {...props}
    />
  )
}

function InputGroupText({ className, ...props }: ReactComponentProps<"span">) {
  return (
    <span
      className={cn(
        "text-(--color-ink-muted) gap-(--spacing-sm) text-(length:--text-body) [&_svg:not([class*='size-'])]:size-(--spacing-lg) flex items-center [&_svg]:pointer-events-none",
        className
      )}
      {...props}
    />
  )
}

function InputGroupInput({
  className,
  ...props
}: ReactComponentProps<"input">) {
  return (
    <Input
      data-slot="input-group-control"
      className={cn("rounded-none border-0 bg-transparent shadow-(--ui-elevation-none) ring-0 focus-visible:ring-0 disabled:bg-transparent aria-invalid:ring-0 dark:bg-transparent dark:disabled:bg-transparent flex-1", className)}
      {...props}
    />
  )
}

function InputGroupTextarea({
  className,
  ...props
}: ReactComponentProps<"textarea">) {
  return (
    <Textarea
      data-slot="input-group-control"
      className={cn("rounded-none border-0 bg-transparent py-(--spacing-sm) shadow-(--ui-elevation-none) ring-0 focus-visible:ring-0 disabled:bg-transparent aria-invalid:ring-0 dark:bg-transparent dark:disabled:bg-transparent flex-1 resize-none", className)}
      {...props}
    />
  )
}

export {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupText,
  InputGroupInput,
  InputGroupTextarea,
}

