  children,
  placement = "bottom start",
  offset = 4,
  crossOffset = 0,
  ...props
}: Omit<
  ReactComponentProps<typeof PopoverPrimitive>,
  "className" | "children"
> & {
  className?: string
  children?: ReactNode
}) {
  return (
