        className
      )}
      {...props}
    >
      {children}
    </PopoverPrimitive>
  )
}

function SelectList<T extends object>({
  className,
  ...props
}: ListBoxProps<T>) {
  return (
    <ListBoxPrimitive
      data-slot="select-list"
      className={cn(
        "group/select-list max-h-[inherit] overflow-x-hidden overflow-y-auto p-0 focus-visible:outline-solid focus-visible:outline-(length:--ui-border-focus) focus-visible:outline-offset-(--ui-focus-offset) focus-visible:outline-(--color-focus-ring)",
        className
      )}
      {...props}
    />
  )
}

function SelectInput({ className, ...props }: SearchFieldProps) {
  return (
    <SearchField
      {...props}
      autoFocus
      data-slot="select-input-wrapper"
      className={cn("p-(--spacing-xs) pb-0", className)}
    >
      <InputGroup>
        <InputGroupInput
          data-slot="select-input"
          className="[&::-webkit-search-cancel-button]:hidden"
        />
        <InputGroupAddon>
          <LibraryIcon asset="assets.icon-search" className="size-(--spacing-lg) shrink-0 opacity-(--ui-alpha-disabled)" />
        </InputGroupAddon>
      </InputGroup>
    </SearchField>
  )
}

function SelectLabel({
  className,
  ...props
}: ReactComponentProps<typeof HeaderPrimitive>) {
  return (
    <HeaderPrimitive
      data-slot="select-label"
      className={cn("text-(--color-ink-muted) px-(--spacing-sm) py-(--spacing-xs) text-(length:--text-caption) font-(family-name:--font-body)", className)}
      {...props}
    />
  )
}

function SelectItem({
  className,
  children,
  ...props
}: ReactComponentProps<typeof ListBoxItemPrimitive>) {
  return (
    <ListBoxItemPrimitive
      data-slot="select-item"
      textValue={typeof children === "string" ? children : undefined}
      className={cn(
        "focus:bg-(--color-surface-selected) focus:text-(--color-ink-primary) not-data-[variant=destructive]:focus:**:text-(--color-ink-primary) gap-(--spacing-sm) rounded-(--radius-control) py-(--spacing-xs) pr-(--spacing-2xl) pl-(--spacing-sm) text-(length:--text-body) [&_svg:not([class*='size-'])]:size-(--spacing-lg) *:[span]:last:flex *:[span]:last:items-center *:[span]:last:gap-(--spacing-sm) data-focused:bg-(--color-surface-selected) data-focused:text-(--color-ink-primary) relative flex w-full cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-(--ui-alpha-disabled) [&_svg]:pointer-events-none [&_svg]:shrink-0",
        className
      )}
      {...props}
    >
      {composeRenderProps(children, (children, { isSelected }) => (
        <>
          <span className="flex flex-1 gap-(--spacing-sm) shrink-0 whitespace-nowrap">
            {children}
          </span>
          <span className="pointer-events-none absolute right-(--spacing-sm) flex size-(--spacing-lg) items-center justify-center">
            {isSelected ? (
              <LibraryIcon asset="assets.icon-check" className="pointer-events-none" />
            ) : null}
          </span>
        </>
      ))}
    </ListBoxItemPrimitive>
  )
}

function SelectSeparator({
  className,
  ...props
}: ReactComponentProps<typeof SeparatorPrimitive>) {
  return (
    <SeparatorPrimitive
      data-slot="select-separator"
      className={cn("bg-(--color-line-base) -mx-(--spacing-xs) my-(--spacing-xs) h-(--ui-border-hairline) pointer-events-none", className)}
      {...props}
    />
  )
}

function SelectEmpty({ className, ...props }: ReactComponentProps<"div">) {
  return (
    <div
      data-slot="select-empty"
      className={cn("text-(--color-ink-muted) hidden w-full justify-center py-(--spacing-sm) text-center text-(length:--text-body) group-data-empty/select-list:flex", className)}
      {...props}
    />
  )
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectInput,
  SelectItem,
  SelectLabel,
  SelectList,
  SelectPopover,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
  SelectEmpty,
}
